def pancake_sort(arr):
    n = len(arr)
    for size in range(n, 0, -1):
        max_idx = arr.index(max(arr[:size + 1]))

        if max_idx != size:
            if max_idx != 0:
                flip(arr, max_idx + 1)
                flip(arr, size + 1)
            else:
                flip(arr, size + 1)

def flip(arr, k):
    arr[:k] = list(reversed(arr[:k]))

assert pancake_sort([15, 79, 25, 38, 69]) == [15, 25, 38, 69, 79]
